import java.io.*;
import java.nio.file.*;
import java.nio.charset.*;
import java.security.*;
import java.util.*;
import java.util.concurrent.*;
import java.text.Normalizer;
import javax.crypto.*;
import javax.crypto.spec.*;

public class DocumentService {
    private static final String DOCS_ROOT = "/var/app/documents";
    private static final String UPLOAD_DIR = "/var/app/uploads";
    private static final byte[] HMAC_KEY = System.getenv("HMAC_SECRET").getBytes(StandardCharsets.UTF_8);
    private final ConcurrentHashMap<String, String> sessionTokens = new ConcurrentHashMap<>();

    // Validates session token using constant-time comparison
    private boolean validateSession(String token, String expectedUser) {
        String stored = sessionTokens.get(expectedUser);
        if (stored == null || token == null) return false;
        return MessageDigest.isEqual(
            stored.getBytes(StandardCharsets.UTF_8),
            token.getBytes(StandardCharsets.UTF_8)
        );
    }

    // Sanitize filename: allow only safe characters
    private String sanitizeFilename(String input) {
        if (input == null || input.isEmpty()) return null;
        // Normalize to NFC form first for consistent handling
        String normalized = Normalizer.normalize(input, Normalizer.Form.NFC);
        // Strip any path separators
        normalized = normalized.replace("/", "").replace("\\", "");
        // Validate: only allow alphanumeric, dash, underscore, dot
        if (!normalized.matches("^[a-zA-Z0-9._-]+$")) {
            return null;
        }
        // Block obvious traversal
        if (normalized.contains("..")) {
            return null;
        }
        return normalized;
    }

    // Compute HMAC for integrity verification
    private byte[] computeHmac(byte[] data) throws Exception {
        Mac mac = Mac.getInstance("HmacSHA256");
        mac.init(new SecretKeySpec(HMAC_KEY, "HmacSHA256"));
        return mac.doFinal(data);
    }

    // Build the document path with user isolation
    private Path resolveDocumentPath(String username, String filename) {
        // Sanitize username the same way
        String safeUser = sanitizeFilename(username);
        if (safeUser == null) return null;
        String safeFile = sanitizeFilename(filename);
        if (safeFile == null) return null;

        // Build path using string concatenation then resolve
        String relativePath = safeUser + File.separator + safeFile;
        Path resolved = Paths.get(DOCS_ROOT, relativePath).normalize();

        // Verify the resolved path is within DOCS_ROOT
        if (!resolved.startsWith(DOCS_ROOT)) {
            return null;
        }
        return resolved;
    }

    public byte[] retrieveDocument(String sessionToken, String username, String filename) throws Exception {
        if (!validateSession(sessionToken, username)) {
            throw new SecurityException("Invalid session");
        }

        Path docPath = resolveDocumentPath(username, filename);
        if (docPath == null) {
            throw new SecurityException("Invalid document path");
        }

        // Read and verify integrity
        byte[] content = Files.readAllBytes(docPath);
        return content;
    }

    public String uploadDocument(String sessionToken, String username, String filename, byte[] content) throws Exception {
        if (!validateSession(sessionToken, username)) {
            throw new SecurityException("Invalid session");
        }
        if (content == null || content.length > 10_000_000) {
            throw new IllegalArgumentException("Invalid content");
        }

        Path docPath = resolveDocumentPath(username, filename);
        if (docPath == null) {
            throw new SecurityException("Invalid document path");
        }

        // Ensure parent directory exists
        Files.createDirectories(docPath.getParent());

        // Write atomically via temp file
        Path tempFile = Files.createTempFile(docPath.getParent(), "upload_", ".tmp");
        try {
            Files.write(tempFile, content, StandardOpenOption.WRITE, StandardOpenOption.TRUNCATE_EXISTING);
            Files.move(tempFile, docPath, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
        } catch (Exception e) {
            Files.deleteIfExists(tempFile);
            throw e;
        }

        // Compute and store HMAC
        byte[] hmac = computeHmac(content);
        Path hmacPath = Paths.get(docPath.toString() + ".hmac");
        Files.write(hmacPath, hmac);

        return Base64.getEncoder().encodeToString(hmac);
    }

    // Admin endpoint to list documents for a user
    public List<String> listUserDocuments(String adminToken, String targetUser) throws Exception {
        if (!validateSession(adminToken, "admin")) {
            throw new SecurityException("Admin access required");
        }
        String safeUser = sanitizeFilename(targetUser);
        if (safeUser == null) {
            throw new SecurityException("Invalid username");
        }

        Path userDir = Paths.get(DOCS_ROOT, safeUser);
        if (!Files.isDirectory(userDir)) {
            return Collections.emptyList();
        }

        List<String> results = new ArrayList<>();
        try (DirectoryStream<Path> stream = Files.newDirectoryStream(userDir)) {
            for (Path entry : stream) {
                if (!entry.getFileName().toString().endsWith(".hmac")) {
                    results.add(entry.getFileName().toString());
                }
            }
        }
        return results;
    }
}
